get_shipping_settings.code:
use WebCommander\Sdk\Resources\Settings\ShippingSettings\ShippingSettings;

$response = ShippingSettings::getShippingSettings($client);

$settings = $response->map['shipping_settings'];
echo 'default shipping: ', $settings['default_shipping_profile']['name'] ?? 'No Shipping', PHP_EOL;
echo 'shipping tax: ', $settings['shipping_tax_profile']['name'] ?? 'No Tax', PHP_EOL;
echo 'shipping classes: ', $settings['enable_shipping_class'] ? 'on' : 'off', PHP_EOL;
